# Test what happens with raise_from when into is a class
import sys
sys.path.insert(0, '/root/repo')

from funcy.compat import raise_from

try:
    raise ValueError("test")
except ValueError as e:
    try:
        raise_from(TypeError, e)
    except TypeError as te:
        print(f"Caught TypeError: {te}")
        print(f"Type: {type(te)}")
        print(f"Args: {te.args}")
